package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class AnimationDrawable extends DrawableContainer implements Animatable { private boolean running,oneShot; public void addFrame(Drawable d,int duration){add(d);} public int getNumberOfFrames(){return children.length;} public Drawable getFrame(int i){return children[i];} public int getDuration(int i){return 0;} public void setOneShot(boolean b){oneShot=b;} public boolean isOneShot(){return oneShot;} public void start(){running=true;} public void stop(){running=false;} public boolean isRunning(){return running;} }